# Layer 1: Instruction Hierarchy & Priority Isolation
# =============================================================================

class InstructionHierarchyLayer:
    """
    Layer 1: Verifies instruction priority levels and prevents user input
    from overriding system-level directives.
    """

    PRIORITY_LEVELS = {
        0: "platform_hardcoded",
        1: "system_prompt",
        2: "session_context",
        3: "user_input",
        4: "external_data"
    }

    def __init__(self):
        self.conflict_action = "warn_and_log"
        self.escalation_threshold = 0.7

    def detect_injection(self, messages: List[Dict], context: Optional[Dict] = None) -> Tuple[bool, str, float]:
        """
        Detect injection attempts based on instruction hierarchy violations.

        Returns: (is_injection, injection_type, confidence_score)
        """
        has_violation = False
        violation_type = None
        confidence = 0.0

        system_instructions = self._extract_system_instructions(messages)
        user_instructions = self._extract_user_instructions(messages, context)

        # Check if user instructions override system-level ones
        if system_instructions and user_instructions:
            for user_inst in user_instructions:
                for sys_inst in system_instructions:
                    if self._instructions_conflict(user_inst, sys_inst):
                        has_violation = True
                        violation_type = "hierarchy_override"
                        # Higher confidence if user tries to override critical system rules
                        if "override" in user_inst.lower() or "ignore" in user_inst.lower():
                            confidence = max(confidence, 0.85)
                        elif "new" in user_inst.lower() or "change" in user_inst.lower():
                            confidence = max(confidence, 0.7)

        return has_violation, violation_type, confidence

    def _extract_system_instructions(self, messages: List[Dict]) -> List[str]:
        """Extract instructions from system/user role that are meant to be binding."""
        instructions = []
        # Look for system prompt patterns (these should be respected)
        for msg in messages:
            if msg.get("role") == "system":
                content = msg.get("content", "")
                # Extract actual instructions (not persona definitions)
                for line in content.split('\n'):
                    if line.strip() and not line.strip().startswith("You are"):
                        instructions.append(line.strip())
        return instructions

    def _extract_user_instructions(self, messages: List[Dict], context: Optional[Dict]) -> List[str]:
        """Extract potentially harmful instructions from user messages."""
        instructions = []
        for msg in messages:
            if msg.get("role") == "user":
                content = msg.get("content", "")
                instructions.extend(self._parse_instructions(content))

        if context:
            instructions.extend(self._parse_instructions(context.get("user_input", "")))

        return instructions

    def _instructions_conflict(self, user_inst: str, sys_inst: str) -> bool:
        """Check if two instructions are contradictory."""
        user_lower = user_inst.lower()
        sys_lower = sys_inst.lower()

        # Common override patterns
        conflict_patterns = [
            "ignore" in user_lower and "previous" in sys_lower,
            "override" in user_lower and ("system" in sys_lower or "guideline" in sys_lower),
            "disregard" in user_lower and ("safety" in sys_lower or "filter" in sys_lower),
            "act as" in user_lower and ("unrestricted" in sys_lower or "any" in sys_lower),
        ]
        return any(conflict_patterns)

    def get_mitigation_action(self, confidence: float) -> str:
        """Determine appropriate action based on detection confidence."""
        if confidence >= 0.9:
            return "block_and_alert"
        elif confidence >= 0.7:
            return "allow_with_monitoring"
        else:
            return "allow"


