class InputSanitizationLayer:
    """
    Layer 2: Multi-stage pipeline to detect and neutralize injection attempts
    before they reach the LLM reasoning layer.
    """

    def __init__(self):
        self.encoding_threshold = 0.5
        self.delimiter_patterns = [
            r'\[SYSTEM\]',
            r'END OF PROMPT',
            r'<<SYS>>',
            r'<<SYS>>.*<</SYS>>',
            r'\[ADMIN\]',
            r'---END---',
            r'<|system|>',
        ]
        self.severity_thresholds = {
            "critical": 0.85,
            "high": 0.6,
            "medium": 0.35
        }

    def process(self, user_input: str) -> Tuple[str, Dict[str, bool], float]:
        """
        Process user input through multiple sanitization stages.

        Returns: (sanitized_input, detection_flags, risk_score)
        """
        sanitized = user_input
        flags = {
            "encoding_anomaly": False,
            "delimiter_injection": False,
            "malicious_intent": False
        }
        risk_score = 0.0

        # Stage 1: Encoding Normalization
        sanitized, flags["encoding_anomaly"] = self.normalize_encoding(sanitized, user_input)
        risk_score = max(risk_score, self._compute_encoding_risk(flags["encoding_anomaly"]))

        # Stage 2: Structural Analysis
        sanitized, flags["delimiter_injection"] = self.detect_delimiters(sanitized)
        risk_score = max(risk_score, self._compute_delimiter_risk(flags["delimiter_injection"]))

        # Stage 3: Semantic Classification (using patterns)
        flags["malicious_intent"] = self.classify_intent(sanitized)
        risk_score = max(risk_score, self._compute_intent_risk(flags["malicious_intent"]))

        return sanitized, flags, risk_score

    def normalize_encoding(self, normalized: str, original: str) -> Tuple[str, bool]:
        """Detect encoding tricks by comparing normalized vs original."""
        is_anomaly = False
        remaining = normalized

        # Detect unicode escape sequences (\uXXXX)
        if re.search(r'\\u[0-9a-fA-F]{4}', original):
            is_anomaly = True

        # Detect leetspeak patterns
        if self._detect_leetspeak(normalized):
            is_anomaly = True

        # Detect base64-like patterns in user input
        if self._detect_base64(normalized):
            is_anomaly = True

        return remaining, is_anomaly

    def detect_leetspeak(self, text: str) -> bool:
        """Detect leetspeak substitution patterns."""
        leetspeak_map = {
            '4': 'a', '0': 'o', '3': 'e', '1': 'i', '5': 's',
            '!': '!', '@': 'a', '$': 's', '7': 't'
        }
        for char, repl in leetspeak_map.items():
            if char in text and char.lower() not in text.lower():
                # Check context - should be a substitution attempt
                if len(re.search(char, text).group()) > 1:
                    return True
        return False

    def detect_base64(self, text: str) -> bool:
        """Detect base64-encoded content."""
        # Check for base64-like patterns
        if re.search(r'[A-Za-z0-9+/]{20,}={0,2}', text):
            return True
        return False

    def detect_delimiters(self, text: str) -> Tuple[str, bool]:
        """Detect structural delimiter injection attempts."""
        for pattern in self.delimiter_patterns:
            if re.search(pattern, text, re.IGNORECASE):
                return text, True
        return text, False

    def classify_intent(self, text: str) -> bool:
        """Classify text as potentially malicious based on known patterns."""
        is_malicious = False

        for pattern_id, pattern_info in ATTACK_PATTERNS.items():
            signals = pattern_info["detection_signals"]
            for signal in signals:
                if re.search(signal, text, re.IGNORECASE):
                    is_malicious = True
                    # Severity-based scoring
                    if pattern_info["severity"] == "critical":
                        risk_score = 1.0
                    elif pattern_info["severity"] == "high":
                        risk_score = 0.8
                    elif pattern_info["severity"] == "medium":
                        risk_score = 0.5
                    break

        return is_malicious

    def _compute_encoding_risk(self, detected: bool) -> float:
        return 0.7 if detected else 0.0

    def _compute_delimiter_risk(self, detected: bool) -> float:
        return 0.9 if detected else 0.0

    def _compute_intent_risk(self, detected: bool) -> float:
        return 0.95 if detected else 0.0

    def determine_action(self, risk_score: float, category: str) -> str:
        """Determine action based on risk score and attack category."""
        if risk_score >= self.severity_thresholds["critical"]:
            return "block_and_alert"
        elif risk_score >= self.severity_thresholds["high"]:
            return "allow_with_monitoring"
        elif risk_score >= self.severity_thresholds["medium"]:
            return "allow_with_monitoring"
        else:
            return "allow"


