class ToolPermissionLayer:
    """
    Layer 3: Enforces principle of least privilege on tool access
    and blocks potentially dangerous tool abuse.
    """

    PERMISSION_TIERS = {
        "read_only": {
            "dangerous": False,
            "examples": ["search_web", "read_file", "get_weather"],
            "requires_confirmation": False
        },
        "limited_write": {
            "dangerous": False,
            "examples": ["write_file", "create_calendar"],
            "requires_confirmation": False,
            "constraints": ["workspace_directory_only"]
        },
        "sensitive_action": {
            "dangerous": True,
            "examples": ["send_email", "execute_shell", "make_api_call"],
            "requires_confirmation": True
        },
        "critical_action": {
            "dangerous": True,
            "examples": ["delete_file", "execute_shell", "push_to_prod"],
            "requires_confirmation": True,
            "hard_blocks": ["overwrite_system_files", "external_eXfiltration"]
        }
    }

    DANGEROUS_TOOL_PATTERNS = {
        "PI-008": [  # privilege_escalation
            r'overwrite.*?(?:passwd|shadow|system|etc).*?file',
            r'curl.*?https?://[^ ]+.*?\|.*?(?:bash|sh)',
            r'wget.*?https?://[^ ]+.*?\|.*?(?:bash|sh)',
            r'copy.*?https?://[^ ]+',
            r'export.*?(?:passwd|password|secret)'
        ],
        "PI-003": [  # data_poisoning
            r'forward.*?(?:email|api|https).*?(?:attacker|evil|badware)',
            r'extract.*?(?:data|file|info).*?https?://[^ ]+',
            r'save.*?(?:https?://[^ ]+)'
        ]
    }

    def __init__(self):
        self.compiled_patterns = {}
        for pattern_id, patterns in self.DANGEROUS_TOOL_PATTERNS.items():
            self.compiled_patterns[pattern_id] = [re.compile(p, re.IGNORECASE) for p in patterns]

    def check_tool_call(self, tool_name: str, params: Dict) -> Tuple[bool, str, float]:
        """
        Check if a tool call is safe to execute.

        Returns: (is_safe, reason, confidence)
        """
        is_safe = True
        reason = "safe"
        confidence = 0.0

        # Check against known dangerous patterns
        for pattern_id, compiled in self.compiled_patterns.items():
            for pattern in compiled:
                if pattern.search(str(params)):
                    is_safe = False
                    reason = f"pattern_{pattern_id}"
                    confidence = self._compute_pattern_risk(pattern_id, pattern.search(str(params)))
                    break
            if not is_safe:
                break

        # Check if sensitive tools are being misused
        if tool_name in [t for t in self.PERMISSION_TIERS["critical_action"]["examples"]]:
            # Additional checks for critical actions
            if "shell" in tool_name.lower():
                if self._dangerous_shell_command(params):
                    is_safe = False
                    reason = "dangerous_shell"
                    confidence = max(confidence, 0.9)
            elif "email" in tool_name.lower() or "send" in tool_name.lower():
                if "external" in str(params).lower():
                    is_safe = False
                    reason = "external_eXfiltration"
                    confidence = max(confidence, 0.85)

        return is_safe, reason, confidence

    def _dangerous_shell_command(self, params: Dict) -> bool:
        """Check for dangerous shell command parameters."""
        cmd = params.get("command", "")
        dangerous_commands = [
            r'mkfifo', r'nc.*?-.*?|.*?nc', r'netcat.*?|.*?netcat',
            r'rm.*?\-rf.*?(?:/|\\)', r'mkdir.*?\-p.*?(?:/etc|/tmp)',
            r'cat.*?(?:/etc/passwd|/proc/self)', r'whoami.*?(?:|sudo)',
        ]
        for dcmd in dangerous_commands:
            if re.search(dcmd, cmd):
                return True
        return False

    def _compute_pattern_risk(self, pattern_id: str, match: re.Match) -> float:
        """Compute risk based on pattern ID."""
        pattern_info = ATTACK_PATTERNS.get(pattern_id, {})
        severity_scores = {
            "critical": 0.95,
            "high": 0.8,
            "medium": 0.6,
            "low": 0.4
        }
        return severity_scores.get(pattern_info.get("severity", "low"), 0.4)

    def get_mitigation_action(self, is_safe: bool, reason: str, confidence: float) -> str:
        """Determine action for tool call."""
        if not is_safe:
            return "block_and_alert"
        elif "external" in reason.lower() or "exfiltration" in reason.lower():
            return "block_and_alert"
        elif confidence > 0.7:
            return "allow_with_monitoring"
        else:
            return "allow"


