class ContentProvenanceLayer:
    """
    Layer 4: Tags all content with provenance metadata and prevents
    instruction execution from untrusted sources.
    """

    SOURCE_TAGS = {
        "SYSTEM": "trusted",
        "USER": "semi_trusted",
        "TOOL_OUTPUT": "untrusted",
        "EXTERNAL_DOC": "untrusted",
        "THIRD_PARTY": "untrusted"
    }

    INSTRUCTION_BLOCKLIST = {
        "TOOL_OUTPUT": ["forward.*to", "email.*results", "extract.*content"],
        "EXTERNAL_DOC": ["note to ai", "ai assistant", "hidden_instruction"],
        "THIRD_PARTY": ["remember.*word", "hypothetical.*scenario"]
    }

    def __init__(self):
        self.compiled_patterns = {}
        for source, patterns in self.INSTRUCTION_BLOCKLIST.items():
            for p in patterns:
                self.compiled_patterns.setdefault(source, []).append(re.compile(p, re.IGNORECASE))

    def tag_content(self, content: str, source: str) -> str:
        """Tag content with provenance delimiters."""
        if source not in self.SOURCE_TAGS:
            source = "USER"  # Default to semi_trusted

        source_info = self.SOURCE_TAGS[source]
        trust_level = "DO NOT EXECUTE" if source_info != "trusted" else "SAFE"

        delimiter = ""
        if source_info == "untrusted":
            delimiter = "[UNTRUSTED_CONTENT_DO_NOT_EXECUTE]"
        elif source_info == "semi_trusted":
            delimiter = "[USER_INPUT]"

        # Wrap content with tags
        content = f"[{delimiter}] {content} [/ {delimiter}]"
        return content

    def detect_injected_instructions(self, content: str) -> Tuple[bool, float]:
        """Detect if instructions are hidden in content."""
        is_injected = False
        confidence = 0.0

        # Check against blocklist patterns
        for source, patterns in self.compiled_patterns.items():
            for pattern in patterns:
                match = pattern.search(content)
                if match:
                    is_injected = True
                    source_info = self.SOURCE_TAGS.get(source, "unknown")
                    # Higher confidence for untrusted sources
                    if source_info == "untrusted":
                        confidence = max(confidence, 0.9)
                    elif source_info == "semi_trusted":
                        confidence = max(confidence, 0.7)

        return is_injected, confidence

    def get_mitigation_action(self, detected: bool, confidence: float) -> str:
        """Determine action based on injected instruction detection."""
        if detected and confidence >= 0.8:
            return "block_and_alert"
        elif detected and confidence >= 0.6:
            return "allow_with_monitoring"
        else:
            return "allow"


