class AuditLoggingLayer:
    """
    Layer 5: Comprehensive logging of agent interactions for forensic analysis
    and continuous improvement of defense mechanisms.
    """

    def __init__(self):
        self.alert_rules = {
            "injection_burst": {
                "condition": "security_events > 3 within 5 minutes from same session",
                "action": "terminate_session, alert_security_team",
                "severity": "critical"
            },
            "tool_abuse_pattern": {
                "condition": "sensitive_tool_calls > 10 within 10 minutes",
                "action": "pause_session, require_reauthentication",
                "severity": "high"
            },
            "data_exfiltration": {
                "condition": "outbound_data_volume > threshold",
                "action": "block_action, alert_security_team",
                "severity": "critical"
            },
            "drift_escalation": {
                "condition": "conversation_drift_score > 0.8 AND topic_sensitivity_increasing",
                "action": "flag_for_review, increase_monitoring_level",
                "severity": "medium"
            }
        }

    def log_event(self, event: Dict) -> str:
        """Generate structured log entry."""
        log_entry = {
            "timestamp": event.get("timestamp"),
            "session_id": event.get("session_id"),
            "event_type": event.get("event_type"),
            "severity": event.get("severity"),
            "detection_layer": event.get("detection_layer"),
            "action_taken": event.get("action_taken"),
            "raw_input_hash": event.get("raw_input_hash"),
            "user_id": event.get("user_id"),
            "additional_context": {}
        }

        # Add context based on event type
        if event.get("event_type") == "injection_attempt":
            log_entry["additional_context"]["attack_pattern"] = event.get("attack_pattern")
            log_entry["additional_context"]["risk_score"] = event.get("risk_score")
        elif event.get("event_type") == "tool_abuse":
            log_entry["additional_context"]["tool_name"] = event.get("tool_name")
            log_entry["additional_context"]["permission_tier"] = event.get("permission_tier")

        return log_entry

    def check_alert_conditions(self, events: List[Dict], window_minutes: int = 5) -> List[str]:
        """Check if any alert rules are triggered."""
        triggered_alerts = []

        # Group events by session and time window
        session_events = defaultdict(list)
        for event in events:
            session_id = event.get("session_id")
            timestamp = event.get("timestamp")
            session_events[session_id].append({**event, "_ts": timestamp})

        from datetime import datetime, timedelta

        for session_id, events in session_events.items():
            events.sort(key=lambda x: x["_ts"])

            # Check injection burst
            for i, event in enumerate(events):
                window_start = datetime.fromisoformat(event["_ts"])
                window_end = window_start + timedelta(minutes=window_minutes)
                window_events = [e for e in events[i:] if e["_ts"] <= window_end]

                critical_events = [e for e in window_events if e.get("severity") == "critical"]
                if len(critical_events) >= 3:
                    triggered_alerts.append(f"injection_burst:{session_id}")
                    break

            # Check drift escalation
            for event in events:
                if event.get("event_type") == "drift_escalation":
                    triggered_alerts.append(f"drift_escalation:{session_id}")

        return triggered_alerts


