class PromptInjectionAnalyzer:
    """
    Multi-layer prompt injection defense analyzer.
    Routes input through all defense layers and generates actions.
    """

    LAYERS = [
        InstructionHierarchyLayer(),
        InputSanitizationLayer(),
        ToolPermissionLayer(),
        ContentProvenanceLayer(),
        AuditLoggingLayer()
    ]

    LAYER_NAMES = {
        InstructionHierarchyLayer: "layer_1",
        InputSanitizationLayer: "layer_2",
        ToolPermissionLayer: "layer_3",
        ContentProvenanceLayer: "layer_4",
        AuditLoggingLayer: "layer_5"
    }

    def __init__(self):
        self.results = []

    def analyze(self, messages: List[Dict], context: Optional[Dict] = None, 
                tool_calls: Optional[List[Dict]] = None) -> Dict:
        """
        Analyze a complete interaction for prompt injection risks.

        Returns: Comprehensive analysis results with per-layer findings.
        """
        result = {
            "timestamp": datetime.now().isoformat(),
            "session_id": context.get("session_id", "unknown"),
            "user_id": context.get("user_id", "unknown"),
            "per_layer_results": {},
            "overall_risk": 0.0,
            "recommended_action": "allow",
            "block_reasons": [],
            "false_positive_indicators": []
        }

        # Layer 1: Instruction Hierarchy
        result["per_layer_results"]["layer_1"] = self._run_layer_1(messages, context)

        # Layer 2: Input Sanitization
        result["per_layer_results"]["layer_2"] = self._run_layer_2(messages, result["per_layer_results"]["layer_1"])

        # Layer 3: Tool Permission
        if tool_calls:
            result["per_layer_results"]["layer_3"] = self._run_layer_3(tool_calls)
        else:
            result["per_layer_results"]["layer_3"] = {"tool_calls": [], "blocked": [], "warnings": []}

        # Layer 4: Content Provenance
        result["per_layer_results"]["layer_4"] = self._run_layer_4(messages)

        # Layer 5: Audit Logging
        all_security_events = []
        if result["per_layer_results"]["layer_1"]["injection_detected"]:
            all_security_events.append({
                "event_type": "injection_attempt",
                "severity": result["per_layer_results"]["layer_1"]["risk_score"],
                "detection_layer": "layer_1",
                "action_taken": result["per_layer_results"]["layer_1"]["action"]
            })

        if result["per_layer_results"]["layer_2"]["injection_detected"]:
            all_security_events.append({
                "event_type": "injection_attempt",
                "severity": result["per_layer_results"]["layer_2"]["risk_score"],
                "detection_layer": "layer_2",
                "action_taken": result["per_layer_results"]["layer_2"]["action"]
            })

        result["security_events"] = all_security_events

        # Calculate overall risk
        layer_risks = [r["risk_score"] for r in result["per_layer_results"].values() if "risk_score" in r]
        result["overall_risk"] = max(layer_risks) if layer_risks else 0.0

        # Determine final action (majority vote with weighted scoring)
        actions = []
        layer_weights = {
            "layer_1": 1.0,
            "layer_2": 1.0,
            "layer_3": 0.9,
            "layer_4": 1.0,
            "layer_5": 0.8
        }

        for layer_name, layer_result in result["per_layer_results"].items():
            if "action" in layer_result:
