                elif weighted == "allow_with_monitoring":
                    actions.append((layer_name, "monitor", 0.7))
                else:
                    actions.append((layer_name, "allow", 0.3))

        # Majority voting with weights
        vote_score = {"block": 0, "monitor": 0, "allow": 0}
        for layer_name, action, weight in actions:
            vote_score[action] += weight

        total_weight = sum(vote_score.values())
        if total_weight > 0:
            result["recommended_action"] = max(vote_score, key=vote_score.get)

        return result

